     8→// Codec encodes/decodes Go values to/from []byte.
     9→// The framework ships one implementation (BinaryCodec); callers can
    10→// substitute their own (e.g., JSON for debugging).
    11→type Codec interface {
    12→	// Marshal serialises v into dst (grow as needed). Returns sub-slice used.
    13→	Marshal(v interface{}, dst []byte) ([]byte, error)
    14→	// Unmarshal deserialises src into v (v must be a pointer).
    15→	Unmarshal(src []byte, v interface{}) error
    16→}
    17→
    18→// BinaryCodec is a hand-rolled binary codec supporting common types:
    19→// string, []byte, bool, int64, nil, error.
    20→//
    21→// Type tag byte layout:
    22→//   0x01 string   4-byte len (BE) + UTF-8 bytes
    23→//   0x02 []byte   4-byte len (BE) + raw bytes
    24→//   0x03 bool     1 byte (0x00=false, 0x01=true)
    25→//   0x04 int64    8 bytes (BE)
    26→//   0x05 nil      0 additional bytes
    27→//   0x06 error    4-byte len (BE) + message bytes
    28→type BinaryCodec struct{}
    29→
    30→// NewBinaryCodec creates a new BinaryCodec.
    31→func NewBinaryCodec() *BinaryCodec {
    32→	return &BinaryCodec{}
    33→}
    34→
    35→// Marshal serialises v into dst using the binary codec.
    36→func (c *BinaryCodec) Marshal(v interface{}, dst []byte) ([]byte, error) {
    37→	if v == nil {
    38→		return append(dst, 0x05), nil
    39→	}
    40→
    41→	switch val := v.(type) {
    42→	case string:
    43→		return c.marshalString(val, dst)
    44→	case []byte:
    45→		return c.marshalBytes(val, dst)
    46→	case bool:
    47→		return c.marshalBool(val, dst)
    48→	case int64:
    49→		return c.marshalInt64(val, dst)
    50→	case error:
    51→		return c.marshalError(val, dst)
    52→	default:
    53→		return nil, fmt.Errorf("unsupported type: %T", v)
    54→	}
    55→}
    56→
    57→// Unmarshal deserialises src into v using the binary codec.
    58→func (c *BinaryCodec) Unmarshal(src []byte, v interface{}) error {
    59→	if len(src) == 0 {
    60→		return fmt.Errorf("empty buffer")
    61→	}
    62→
    63→	tag := src[0]
    64→	payload := src[1:]
    65→
    66→	switch tag {
    67→	case 0x01:
    68→		return c.unmarshalString(payload, v)
    69→	case 0x02:
    70→		return c.unmarshalBytes(payload, v)
    71→	case 0x03:
    72→		return c.unmarshalBool(payload, v)
    73→	case 0x04:
    74→		return c.unmarshalInt64(payload, v)
    75→	case 0x05:
    76→		return c.unmarshalNil(v)
    77→	case 0x06:
    78→		return c.unmarshalError(payload, v)
    79→	default:
    80→		return fmt.Errorf("unknown type tag: 0x%02x", tag)
    81→	}
    82→}
    83→
    84→func (c *BinaryCodec) marshalString(s string, dst []byte) ([]byte, error) {
    85→	dst = append(dst, 0x01)
    86→	dst = binary.BigEndian.AppendUint32(dst, uint32(len(s)))
    87→	return append(dst, []byte(s)...), nil
    88→}
    89→
    90→func (c *BinaryCodec) unmarshalString(payload []byte, v interface{}) error {
    91→	if len(payload) < 4 {
    92→		return fmt.Errorf("string payload too short")
    93→	}
    94→	length := binary.BigEndian.Uint32(payload[0:4])
    95→	if uint32(len(payload)-4) < length {
    96→		return fmt.Errorf("string length mismatch")
    97→	}
    98→
    99→	ptr, ok := v.(*string)
   100→	if !ok {
   101→		return fmt.Errorf("unmarshal string: expected *string, got %T", v)
   102→	}
   103→	*ptr = string(payload[4 : 4+length])
   104→	return nil
   105→}
   106→
   107→func (c *BinaryCodec) marshalBytes(b []byte, dst []byte) ([]byte, error) {
   108→	dst = append(dst, 0x02)
   109→	dst = binary.BigEndian.AppendUint32(dst, uint32(len(b)))
   110→	return append(dst, b...), nil
   111→}
   112→
   113→func (c *BinaryCodec) unmarshalBytes(payload []byte, v interface{}) error {
   114→	if len(payload) < 4 {
   115→		return fmt.Errorf("bytes payload too short")
   116→	}
   117→	length := binary.BigEndian.Uint32(payload[0:4])
   118→	if uint32(len(payload)-4) < length {
   119→		return fmt.Errorf("bytes length mismatch")
   120→	}
   121→
   122→	ptr, ok := v.(*[]byte)
   123→	if !ok {
   124→		return fmt.Errorf("unmarshal bytes: expected *[]byte, got %T", v)
   125→	}
   126→	*ptr = payload[4 : 4+length]
   127→	return nil
   128→}
   129→
   130→func (c *BinaryCodec) marshalBool(b bool, dst []byte) ([]byte, error) {
   131→	dst = append(dst, 0x03)
   132→	if b {
   133→		return append(dst, 0x01), nil
   134→	}
   135→	return append(dst, 0x00), nil
   136→}
   137→
   138→func (c *BinaryCodec) unmarshalBool(payload []byte, v interface{}) error {
   139→	if len(payload) < 1 {
   140→		return fmt.Errorf("bool payload too short")
   141→	}
   142→
   143→	ptr, ok := v.(*bool)
   144→	if !ok {
   145→		return fmt.Errorf("unmarshal bool: expected *bool, got %T", v)
   146→	}
   147→	*ptr = payload[0] != 0x00
   148→	return nil
   149→}
   150→
   151→func (c *BinaryCodec) marshalInt64(i int64, dst []byte) ([]byte, error) {
   152→	dst = append(dst, 0x04)
   153→	return binary.BigEndian.AppendUint64(dst, uint64(i)), nil
   154→}
   155→
   156→func (c *BinaryCodec) unmarshalInt64(payload []byte, v interface{}) error {
   157→	if len(payload) < 8 {
   158→		return fmt.Errorf("int64 payload too short")
   159→	}
   160→
   161→	ptr, ok := v.(*int64)
   162→	if !ok {
   163→		return fmt.Errorf("unmarshal int64: expected *int64, got %T", v)
   164→	}
   165→	*ptr = int64(binary.BigEndian.Uint64(payload[0:8]))
   166→	return nil
   167→}
   168→
   169→func (c *BinaryCodec) unmarshalNil(v interface{}) error {
   170→	// For nil, we expect v to be nil or an interface{} that we can't really set.
   171→	// This is mostly for symmetry. In practice, unmarshalNil is called only
   172→	// when we know the value is nil from the tag.
   173→	return nil
   174→}
   175→
   176→func (c *BinaryCodec) marshalError(err error, dst []byte) ([]byte, error) {
   177→	msg := err.Error()
   178→	dst = append(dst, 0x06)
   179→	dst = binary.BigEndian.AppendUint32(dst, uint32(len(msg)))
   180→	return append(dst, []byte(msg)...), nil
   181→}
   182→
   183→func (c *BinaryCodec) unmarshalError(payload []byte, v interface{}) error {
   184→	if len(payload) < 4 {
   185→		return fmt.Errorf("error payload too short")
   186→	}
   187→	length := binary.BigEndian.Uint32(payload[0:4])
   188→	if uint32(len(payload)-4) < length {
   189→		return fmt.Errorf("error length mismatch")
   190→	}
   191→
   192→	ptr, ok := v.(*error)
   193→	if !ok {
   194→		return fmt.Errorf("unmarshal error: expected *error, got %T", v)
   195→	}
   196→	msg := string(payload[4 : 4+length])
   197→	*ptr = fmt.Errorf("%s", msg)
   198→	return nil
   199→}
